mapper.insert:
INSERT INTO ai_assistant_proposal_set
  (workspace_id, proposal_key, session_id, origin_turn_id, message_id, requested_by_user_id,
   step_number, call_ordinal, tool_name, invocation_mode, row_count, intent_fingerprint,
   scope_revision, privacy_generation, organization_privacy_generation)
SELECT #{workspaceId}, #{proposalKey}, #{sessionId}, #{originTurnId}, #{messageId},
       #{requestedByUserId}, #{stepNumber}, #{callOrdinal}, #{toolName}, #{invocationMode},
       #{rowCount}, #{intentFingerprint}, #{scopeRevision}, #{privacyGeneration}, #{organizationPrivacyGeneration}
FROM ai_chat_message m
JOIN ai_chat_turn t ON t.workspace_id = m.workspace_id AND t.session_id = m.session_id
JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
WHERE m.workspace_id = #{workspaceId}
  AND m.session_id = #{sessionId}
  AND m.id = #{messageId}
  AND m.author_kind = 'user'
  AND m.author_user_id = #{requestedByUserId}
  AND t.id = #{originTurnId}
  AND t.requested_by_user_id = #{requestedByUserId}
  AND s.organization_privacy_generation = #{organizationPrivacyGeneration}
  AND m.organization_privacy_generation = s.organization_privacy_generation
  AND t.organization_privacy_generation = s.organization_privacy_generation
  AND t.privacy_generation = #{privacyGeneration}

mapper.select:
SELECT p.* FROM ai_assistant_proposal_set p
WHERE p.organization_privacy_generation = #{organizationPrivacyGeneration}
  AND 
  AND p.workspace_id = #{workspaceId} AND p.session_id = #{sessionId}
  AND p.proposal_key = #{proposalKey}

SELECT p.* FROM ai_assistant_proposal_set p
WHERE p.organization_privacy_generation = #{organizationPrivacyGeneration}
  AND 
  AND p.workspace_id = #{workspaceId} AND p.session_id = #{sessionId}
  AND p.proposal_key = #{proposalKey}
FOR UPDATE

SELECT p.* FROM ai_assistant_proposal_set p
WHERE p.organization_privacy_generation = #{organizationPrivacyGeneration}
  AND 
  AND p.workspace_id = #{workspaceId} AND p.session_id = #{sessionId}
  AND p.origin_turn_id = #{originTurnId} AND p.step_number = #{stepNumber}
  AND p.call_ordinal = #{callOrdinal}
